shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-dark: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --crimson: #8f281e;
    --navy-bg: #0f1d2b;
    --navy-card: #16293b;
    --navy-line: #274059;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans-cn: 'Noto Sans SC', 'PingFang SC', sans-serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', serif;
    --font-serif-en: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    font-family: var(--font-serif-cn);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.78;
  }

  /* Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Sticky Top Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--ink);
    box-shadow: 0 1px 0 var(--line);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.7rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .masthead-brand {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
  }

  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    border-left: 1px solid var(--line-strong);
    padding-left: 0.85rem;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--ink);
    border-radius: 2px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.35rem 0.75rem;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero-header {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }

  .hero-kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--crimson);
  }

  .kicker-pill {
    background: var(--crimson);
    color: #fff;
    padding: 0.18rem 0.55rem;
    font-weight: 700;
    letter-spacing: 0.1em;
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(2.1rem, 4.3vw, 3.55rem);
    line-height: 1.18;
    color: var(--ink);
    margin-bottom: 1.35rem;
    max-width: 980px;
    letter-spacing: -0.015em;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.26;
    letter-spacing: 0.01em;
  }

  .hero-dek {
    font-size: clamp(1.06rem, 1.6vw, 1.28rem);
    line-height: 1.65;
    color: var(--muted);
    max-width: 840px;
    margin-bottom: 2rem;
    font-weight: 400;
    border-left: 3px solid var(--accent);
    padding-left: 1.1rem;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.2rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-name {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }

  .meta-Specs {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    display: flex;
    gap: 1.25rem;
  }

  /* Quick Key Numbers Strip */
  .key-figures-strip {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    border-bottom: 1px solid var(--line-strong);
    background: var(--paper-card);
  }

  .figure-cell {
    padding: 1.35rem 1.5rem;
    border-right: 1px solid var(--line);
  }

  .figure-cell:last-child {
    border-right: none;
  }

  .figure-num {
    font-family: var(--font-display);
    font-size: 1.9rem;
    font-weight: 800;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .figure-num span.accent-unit {
    color: var(--crimson);
    font-size: 1.1rem;
    font-family: var(--font-mono);
    margin-left: 0.2rem;
  }

  .figure-label {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--body);
    text-transform: uppercase;
    letter-spacing: 0.04em;
    margin-bottom: 0.2rem;
  }

  .figure-sub {
    font-family: var(--font-sans);
    font-size: 0.74rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Main Editorial Grid */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3rem 1.5rem 4.5rem;
  }

  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 7fr) minmax(280px, 4.2fr);
    gap: 3.5rem;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .sidebar-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2rem;
    position: sticky;
    top: 4.5rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.55rem;
    letter-spacing: 0.005em;
  }

  .prose-p.lead-para {
    font-size: 1.26rem;
    line-height: 1.75;
    color: var(--ink);
    font-weight: 600;
    border-left: 4px solid var(--crimson);
    padding-left: 1.15rem;
    margin-bottom: 1.85rem;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Section Dividers */
  .section-marker {
    margin: 2.8rem 0 1.6rem;
    padding-top: 1.5rem;
    border-top: 2px solid var(--ink);
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
  }

  .section-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
  }

  .section-heading {
    font-family: var(--font-display);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Dossier & Callout Cards in Sidebar */
  .rail-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.5rem;
  }

  .rail-card-header {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.65rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .rail-card-title {
    font-family: var(--font-display);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.9rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line);
  }

  .ctx-text {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    line-height: 1.68;
    color: var(--body);
  }

  /* Derived Pull Quote */
  .pull-quote {
    background: var(--paper-card);
    border-left: 4px solid var(--accent);
    padding: 1.4rem 1.5rem;
    margin: 0;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.18rem;
    line-height: 1.52;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.75rem;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Bespoke SVG Diagram Container */
  .diagram-panel {
    margin: 2.5rem 0;
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 2rem 1.75rem;
    border-radius: 2px;
    border-top: 4px solid var(--accent);
    box-shadow: 0 10px 28px rgba(15, 29, 43, 0.12);
  }

  .diagram-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #e3924f;
    margin-bottom: 0.35rem;
  }

  .diagram-title {
    font-family: var(--font-display);
    font-size: 1.32rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 0.45rem;
  }

  .diagram-subtitle {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    color: #b4c2d0;
    margin-bottom: 1.5rem;
    line-height: 1.5;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
  }

  .diagram-footnote {
    margin-top: 1rem;
    padding-top: 0.85rem;
    border-top: 1px solid var(--navy-line);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: #8fa3b8;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Full-Bleed Mid-Article Feature Quote Box (for p9) */
  .pentagon-statement-box {
    margin: 2.25rem 0;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 5px solid var(--ink);
    padding: 1.75rem 2rem;
    position: relative;
  }

  .statement-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--crimson);
    font-weight: 700;
    margin-bottom: 0.65rem;
  }

  .statement-prose {
    font-family: var(--font-display);
    font-size: 1.28rem;
    line-height: 1.55;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0;
  }

  /* Political & Moral Backlash Matrix */
  .backlash-matrix {
    margin: 2.5rem 0;
    border: 1px solid var(--line-strong);
    background: #fffdf9;
  }

  .matrix-header {
    background: var(--ink);
    color: var(--paper);
    padding: 1rem 1.35rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .matrix-title {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
  }

  .matrix-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: #e3924f;
  }

  .matrix-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
  }

  .matrix-cell {
    padding: 1.25rem 1.35rem;
    border-bottom: 1px solid var(--line);
    border-right: 1px solid var(--line);
  }

  .matrix-cell:nth-child(2n) {
    border-right: none;
  }

  .matrix-speaker {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.2rem;
  }

  .matrix-role {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--crimson);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: 0.65rem;
  }

  .matrix-stance {
    font-family: var(--font-serif-cn);
    font-size: 0.92rem;
    line-height: 1.55;
    color: var(--body);
  }

  :host([lang="en"]) .matrix-stance {
    font-family: var(--font-serif-en);
  }

  /* Legal Rule Conflict Callout (Closing) */
  .regulation-conflict-box {
    margin-top: 2rem;
    background: var(--paper-dark);
    border: 1px solid var(--line-strong);
    padding: 1.6rem 1.75rem;
  }

  .reg-badge {
    display: inline-block;
    background: var(--ink);
    color: var(--paper);
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 0.85rem;
  }

  /* Footer */
  .wsj-footer {
    border-top: 3px double var(--line-strong);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
  }

  .footer-inner {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
  }

  /* Responsive Reflow */
  @media (max-width: 960px) {
    .key-figures-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .figure-cell:nth-child(2) {
      border-right: none;
    }
    .figure-cell:nth-child(1),
    .figure-cell:nth-child(2) {
      border-bottom: 1px solid var(--line);
    }
    .asymmetric-grid {
      grid-template-columns: 1fr;
      gap: 2.5rem;
    }
    .sidebar-rail {
      position: static;
    }
  }

  @media (max-width: 600px) {
    .masthead-inner {
      padding: 0.6rem 1rem;
    }
    .wsj-section-tag {
      display: none;
    }
    .hero-header {
      padding: 2.2rem 1rem 1.8rem;
    }
    .key-figures-strip {
      grid-template-columns: 1fr;
    }
    .figure-cell {
      border-right: none !important;
      border-bottom: 1px solid var(--line);
      padding: 1.1rem 1rem;
    }
    .editorial-container {
      padding: 2rem 1rem 3.5rem;
    }
    .matrix-grid {
      grid-template-columns: 1fr;
    }
    .matrix-cell {
      border-right: none !important;
    }
    .diagram-panel {
      padding: 1.35rem 1rem;
    }
    .pentagon-statement-box {
      padding: 1.35rem 1.2rem;
    }
  }
